let scene,camera,renderer,controls,detector,spec,active=0,foundation=[];
let candidates=[];

// 文档坐标 -> Three.js。规格模型坐标为 X=y_doc(下游), Y=x_doc(西北), Z=z-198。
// Three.js 以 Y 竖直，因此场景使用 (Y_model-115.5, Z_model, -X_model)。
const P=([x,y,z])=>new THREE.Vector3(x-115.5,z-198,-y);
const docDirToScene=d=>new THREE.Vector3(d.x,d.z,-d.y).normalize();
const mat=(color,opts={})=>new THREE.MeshStandardMaterial({color,roughness:.78,metalness:.02,...opts});
function addEdges(mesh,color=C.edge,opacity=.5){const l=new THREE.LineSegments(new THREE.EdgesGeometry(mesh.geometry,25),new THREE.LineBasicMaterial({color,transparent:true,opacity}));mesh.add(l)}
function box(group,name,x0,x1,y0,y1,z0,z1,color,opacity=1){const s=new THREE.Vector3(x1-x0,z1-z0,y1-y0),m=new THREE.Mesh(new THREE.BoxGeometry(s.x,s.y,s.z),mat(color,{transparent:opacity<1,opacity,depthWrite:opacity>.72}));m.name=name;m.position.copy(P([(x0+x1)/2,(y0+y1)/2,(z0+z1)/2]));m.castShadow=m.receiveShadow=true;group.add(m);addEdges(m,color===C.dam?C.edge:color,.42);return m}
function extrudeProfile(group,name,x0,x1,profile,color,opacity=.82){const n=profile.length,v=[],idx=[];for(const x of [x0,x1])for(const [y,z] of profile){const p=P([x,y,z]);v.push(p.x,p.y,p.z)}const tri=THREE.ShapeUtils.triangulateShape(profile.map(([y,z])=>new THREE.Vector2(y,z)),[]);for(const t of tri){idx.push(t[0],t[2],t[1],n+t[0],n+t[1],n+t[2])}for(let i=0;i<n;i++){const j=(i+1)%n;idx.push(i,j,n+j,i,n+j,n+i)}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();const m=new THREE.Mesh(g,mat(color,{transparent:opacity<1,opacity,side:THREE.DoubleSide,depthWrite:opacity>.72}));m.name=name;m.castShadow=m.receiveShadow=true;group.add(m);addEdges(m,color===C.dam?C.edge:color,.42);return m}
function foundationAt(x){if(x<=foundation[0][0])return foundation[0][1];if(x>=foundation.at(-1)[0])return foundation.at(-1)[1];for(let i=0;i<foundation.length-1;i++){const [a,za]=foundation[i],[b,zb]=foundation[i+1];if(x>=a&&x<=b){const t=(x-a)/(b-a);return za+(zb-za)*t}}return 198}
function faceAt(z){return 9.7+.83*(298-z)}
function standardDamGeometry(){const v=[],idx=[],n=foundation.length;for(const [x,b] of foundation){for(const q of [[x,0,b],[x,0,306],[x,9.7,306],[x,9.7,298],[x,faceAt(b),b]]){const p=P(q);v.push(p.x,p.y,p.z)}}const cap=(o,flip)=>{for(const a of [[0,1,2],[0,2,3],[0,3,4]])idx.push(...(flip?[o+a[0],o+a[2],o+a[1]]:[o+a[0],o+a[1],o+a[2]]))};cap(0,true);cap((n-1)*5,false);for(let i=0;i<n-1;i++)for(const [a,b] of [[0,1],[1,2],[2,3],[3,4],[4,0]])idx.push(i*5+a,i*5+b,(i+1)*5+b,i*5+a,(i+1)*5+b,(i+1)*5+a);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setIndex(idx);g.computeVertexNormals();return g}
function pointInPoly(y,z,poly){let inside=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [yi,zi]=poly[i],[yj,zj]=poly[j];if(((zi>z)!==(zj>z))&&(y<(yj-yi)*(z-zi)/(zj-zi)+yi))inside=!inside}return inside}
function inRange(v,r){return v>=r[0]-1e-6&&v<=r[1]+1e-6}
function rangesOf(o){return o.x_ranges||[o.x_range]}
function solidContains(x,y,z){if(z<foundationAt(x)-1e-6)return false;for(const s of spec.solids){if(s.type==='extrusion_x'&&rangesOf(s).some(r=>inRange(x,r))&&pointInPoly(y,z,s.profile_yz))return true;if(s.type==='box')for(const b of s.boxes||[])if(inRange(x,b.x)&&inRange(y,b.y)&&inRange(z,b.z))return true}return false}
function interpPath(path,x){for(let i=0;i<path.length-1;i++){const [a,za]=path[i],[b,zb]=path[i+1];if(inRange(x,[Math.min(a,b),Math.max(a,b)])&&Math.abs(b-a)>1e-8)return za+(zb-za)*(x-a)/(b-a)}return null}
function interpFloor(path,y){for(let i=0;i<path.length-1;i++){const [a,za]=path[i],[b,zb]=path[i+1];if(inRange(y,[a,b]))return za+(zb-za)*(y-a)/(b-a)}return null}
function voidContains(x,y,z){for(const q of spec.voids){if(q.type==='box'){const bs=q.boxes||[q];for(const b of bs)if(b.x&&b.y&&b.z&&inRange(x,b.x)&&inRange(y,b.y)&&inRange(z,b.z))return true}else if(q.type==='sweep_xz'){const f=interpPath(q.path_xz,x);if(f!==null&&Math.abs(y-q.y)<=q.width/2&&z>=f&&z<=f+q.height)return true}else if(q.type==='chute'&&q.x_ranges.some(r=>inRange(x,r))){const f=interpFloor(q.floor_yz,y);if(f!==null){const top=y<=37.5?298:306;if(z>=f&&z<=top)return true}}}return false}
function materialAt(x,y,z){if(x<0||x>231||z<198||z>306)return'air';if(solidContains(x,y,z)&&!voidContains(x,y,z))return'concrete';const f=foundationAt(x);if(z<f)return'rock';const up=+$('#upLevel').value,down=+$('#downLevel').value;if(y<0&&z<=up)return'water';if(y>94&&z<=down)return'water';return'air'}

function addSolids(){const dm=new THREE.Mesh(standardDamGeometry(),mat(C.dam,{transparent:true,opacity:.76,side:THREE.DoubleSide}));dm.name='dam_standard';dm.castShadow=dm.receiveShadow=true;groups.dam.add(dm);addEdges(dm);for(const s of spec.solids.filter(s=>s.id!=='dam_standard')){if(s.type==='extrusion_x')for(const r of rangesOf(s))extrudeProfile(groups.dam,s.id,r[0],r[1],s.profile_yz,C.dam,.86);else if(s.type==='box')for(const b of s.boxes||[])box(groups.dam,s.id,b.x[0],b.x[1],b.y[0],b.y[1],b.z[0],b.z[1],C.dam,.82)}}
function tunnelSegment(group,a,b,width,height,color,name){const p=P([a[0],a[1],a[2]+height/2]),q=P([b[0],b[1],b[2]+height/2]),d=q.clone().sub(p),len=d.length(),m=new THREE.Mesh(new THREE.BoxGeometry(len,height,width),mat(color,{transparent:true,opacity:.82,emissive:color,emissiveIntensity:.12}));m.name=name;m.position.copy(p.clone().add(q).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(1,0,0),d.clone().normalize());group.add(m);addEdges(m,color,.7)}
function addVoids(){for(const q of spec.voids){const color=q.id.includes('upper')?C.upper:q.id.includes('lower')?C.lower:q.id.includes('elevator')?C.shaft:q.id.includes('spillway')?C.spill:C.outlet;if(q.type==='sweep_xz')q.path_xz.slice(0,-1).forEach((a,i)=>tunnelSegment(groups.gallery,[a[0],q.y,a[1]],[q.path_xz[i+1][0],q.y,q.path_xz[i+1][1]],q.width,q.height,color,q.id));else if(q.type==='box'){for(const b of q.boxes||[q]){if(!b.x||!b.y||!b.z)continue;box(q.id.includes('gallery')||q.id.includes('obs')||q.id.includes('elevator')?groups.gallery:groups.hydraulic,q.id,b.x[0],b.x[1],b.y[0],b.y[1],b.z[0],b.z[1],color,.66)}}else if(q.type==='chute'){for(const xr of q.x_ranges)for(let i=0;i<q.floor_yz.length-1;i++){const [y0,z0]=q.floor_yz[i],[y1,z1]=q.floor_yz[i+1];const xc=(xr[0]+xr[1])/2,w=xr[1]-xr[0],p=P([xc,y0,z0+.35]),r=P([xc,y1,z1+.35]),d=r.clone().sub(p),m=new THREE.Mesh(new THREE.BoxGeometry(w,.7,d.length()),mat(C.spill,{transparent:true,opacity:.7,emissive:C.spill,emissiveIntensity:.1}));m.position.copy(p.clone().add(r).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),d.normalize());groups.hydraulic.add(m)}}}}
function waterMesh(name,level,upstream){const g=new THREE.PlaneGeometry(231,upstream?300:206);const m=new THREE.Mesh(g,mat(upstream?C.upwater:C.downwater,{transparent:true,opacity:.38,roughness:.18,metalness:.08,side:THREE.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(0,level-198,upstream?150:-197);m.name=name;return m}
function axes(){const g=new THREE.Group(),o=P([18,-4,210]);for(const [q,c] of [[P([18,26,210]),0x49a7ff],[P([48,-4,210]),0xff9f4a],[P([18,-4,235]),0x38d996]]){const d=q.clone().sub(o);g.add(new THREE.ArrowHelper(d.clone().normalize(),o,d.length(),c,5,2.5))}return g}
function defaultCandidates(){return spec.detectors.candidate_sites.map((d,i)=>({name:['A 上层观测室','B 电梯井附近','C 下层观测室','D 南出口平台','E 北出口平台'][i]||d.id,x:d.x,y:Array.isArray(d.y)?(d.y[0]+d.y[1])/2:d.y,z:d.z_floor+.4,az:[90,105,88,230,220][i]||90,el:[25,30,42,20,20][i]||25,fov:[45,45,40,55,55][i]||45}))}

function directionDoc(c,azOffset=0,elOffset=0){const az=THREE.MathUtils.degToRad(c.az+azOffset),el=THREE.MathUtils.degToRad(c.el+elOffset);return new THREE.Vector3(Math.cos(el)*Math.cos(az),Math.cos(el)*Math.sin(az),Math.sin(el)).normalize()}
function rayBox(origin,dir,min,max){let lo=0,hi=500;for(const k of ['x','y','z']){if(Math.abs(dir[k])<1e-9){if(origin[k]<min[k]||origin[k]>max[k])return null;continue}let a=(min[k]-origin[k])/dir[k],b=(max[k]-origin[k])/dir[k];if(a>b)[a,b]=[b,a];lo=Math.max(lo,a);hi=Math.min(hi,b);if(lo>hi)return null}return[lo,hi]}
function traceRay(origin,dir,cell){const min={x:0,y:-300,z:198},max={x:231,y:300,z:306},hit=rayBox(origin,dir,min,max);const totals={concrete:0,water:0,rock:0,air:0},cells=[];if(!hit)return{totals,cells,mwe:0};let t=hit[0]+1e-6,end=hit[1],p=origin.clone().addScaledVector(dir,t),ix=Math.floor((p.x-min.x)/cell),iy=Math.floor((p.y-min.y)/cell),iz=Math.floor((p.z-min.z)/cell);const step={x:Math.sign(dir.x),y:Math.sign(dir.y),z:Math.sign(dir.z)},delta={},next={};for(const k of ['x','y','z']){delta[k]=dir[k]===0?Infinity:Math.abs(cell/dir[k]);const boundary=min[k]+(step[k]>0?(Math.floor((p[k]-min[k])/cell)+1):Math.floor((p[k]-min[k])/cell))*cell;next[k]=dir[k]===0?Infinity:t+(boundary-p[k])/dir[k]}let guard=0;while(t<end-1e-7&&guard++<10000){const tn=Math.min(end,next.x,next.y,next.z),mid=t+(tn-t)/2,mp=origin.clone().addScaledVector(dir,mid),kind=materialAt(mp.x,mp.y,mp.z),len=Math.max(0,tn-t);totals[kind]+=len;cells.push({ix,iy,iz,t0:t,t1:tn,kind});t=tn;for(const k of ['x','y','z'])if(Math.abs(next[k]-tn)<1e-7){if(k==='x')ix+=step.x;if(k==='y')iy+=step.y;if(k==='z')iz+=step.z;next[k]+=delta[k]}}const rho=spec.materials;return{totals,cells,mwe:totals.concrete*rho.concrete.density+totals.water*rho.water.density+totals.rock*rho.rock.density}}
function sampleRays(c,cell){const offsets=[-1,-.5,0,.5,1],half=c.fov/2,arr=[];for(const u of offsets)for(const v of offsets)arr.push(traceRay(new THREE.Vector3(c.x,c.y,c.z),directionDoc(c,u*half,v*half*.7),cell));return arr}
function updateRayVisual(trace,c,dir){groups.grid.clear();const cell=+$('#gridSize').value,im=new THREE.InstancedMesh(new THREE.BoxGeometry(cell,cell,cell),new THREE.MeshBasicMaterial({color:C.grid,wireframe:true,transparent:true,opacity:.18}),trace.cells.length),dummy=new THREE.Object3D();trace.cells.forEach((q,i)=>{dummy.position.copy(P([(q.ix+.5)*cell,(q.iy+.5)*cell-300,(q.iz+.5)*cell+198]));dummy.updateMatrix();im.setMatrixAt(i,dummy.matrix)});groups.grid.add(im);const origin=P([c.x,c.y,c.z]),sdir=docDirToScene(dir),points=[origin];let cursor=95;for(const q of trace.cells){if(q.kind==='air')continue;const a=origin.clone().addScaledVector(sdir,q.t0),b=origin.clone().addScaledVector(sdir,q.t1),col=q.kind==='concrete'?C.dam:q.kind==='water'?C.upwater:C.rock;groups.cone.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a,b]),new THREE.LineBasicMaterial({color:col})));cursor=Math.max(cursor,q.t1)}points.push(origin.clone().addScaledVector(sdir,cursor));const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:C.detector,dashSize:3,gapSize:2,transparent:true,opacity:.9}));line.computeLineDistances();groups.cone.add(line)}
function updateDetector(){if(!scene||!candidates.length)return;groups.cone.clear();const c=candidates[active],p=P([c.x,c.y,c.z]),dirDoc=directionDoc(c),dir=docDirToScene(dirDoc);detector=new THREE.Mesh(new THREE.BoxGeometry(1.6,.5,1.2),mat(C.detector,{emissive:C.detector,emissiveIntensity:.55}));detector.position.copy(p);groups.cone.add(detector);const length=105,r=Math.tan(THREE.MathUtils.degToRad(c.fov/2))*length,cone=new THREE.Mesh(new THREE.ConeGeometry(r,length,32,1,true),new THREE.MeshBasicMaterial({color:C.cone,transparent:true,opacity:.1,side:THREE.DoubleSide,depthWrite:false}));cone.position.copy(p.clone().add(dir.clone().multiplyScalar(length/2)));cone.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.clone().negate());groups.cone.add(cone);groups.cone.add(new THREE.ArrowHelper(dir,p,length,C.detector,5,2));metrics(dirDoc)}
function metrics(dirDoc){const c=candidates[active],cell=+$('#gridSize').value,rays=sampleRays(c,cell),center=rays[12],paths=rays.map(r=>r.totals.concrete),trans=rays.map(r=>Math.exp(-r.mwe/120)),viewTransmission=100*trans.reduce((a,b)=>a+b,0)/trans.length,el=Math.max(0,THREE.MathUtils.degToRad(c.el)),acceptance=Math.max(.05,Math.sin(el))**1.7,count=Math.round(12000*acceptance*trans.reduce((a,b)=>a+b,0)/trans.length),score=Math.round(Math.min(100,.52*viewTransmission+.28*Math.min(100,count/28)+.20*Math.min(100,c.fov/55*100)));$('#path').textContent=center.totals.concrete.toFixed(1)+' m';$('#opacity').textContent=center.mwe.toFixed(0);$('#count').textContent=count>999?(count/1000).toFixed(1)+'k':count;$('#sky').textContent=viewTransmission.toFixed(0)+'%';$('#rayCells').textContent=center.cells.length+' 个';$('#rayRange').textContent=Math.min(...paths).toFixed(0)+'–'+Math.max(...paths).toFixed(0)+' m';$('#score').textContent=score;$('#ring').style.background=`conic-gradient(var(--cyan) 0 ${score}%,#19313c ${score}%)`;$('#grade').textContent=score>=72?'条件可行':score>=48?'需要优化':'风险较高';updateRayVisual(center,c,dirDoc)}

function buildScene(){foundation=[...new Map(spec.foundation_surface.points.map(([x,z])=>[x,Math.min(...spec.foundation_surface.points.filter(p=>p[0]===x).map(p=>p[1]))])).entries()].sort((a,b)=>a[0]-b[0]);scene=new THREE.Scene();scene.background=new THREE.Color(0x071018);scene.fog=new THREE.FogExp2(0x071018,.00155);camera=new THREE.PerspectiveCamera(40,1,.1,1400);camera.position.set(210,150,-260);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;container.append(renderer.domElement);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(0,52,-15);controls.minDistance=50;controls.maxDistance=720;scene.add(new THREE.HemisphereLight(0xbfe3ff,0x17221b,2.4));const sun=new THREE.DirectionalLight(0xfff0d6,3.1);sun.position.set(160,260,150);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);scene.add(sun);
  groups.dam=new THREE.Group();groups.gallery=new THREE.Group();groups.hydraulic=new THREE.Group();groups.upwater=new THREE.Group();groups.downwater=new THREE.Group();groups.cone=new THREE.Group();groups.grid=new THREE.Group();groups.grid.visible=false;addSolids();addVoids();groups.upwater.add(waterMesh('上游库水',+$('#upLevel').value,true));groups.downwater.add(waterMesh('下游尾水',+$('#downLevel').value,false));for(const k of ['dam','gallery','hydraulic','upwater','downwater','grid','cone'])scene.add(groups[k]);scene.add(axes());const ground=new THREE.GridHelper(520,26,0x35505d,0x1d3038);ground.position.y=.05;scene.add(ground);updateDetector();resize();renderer.setAnimationLoop(()=>{controls.update();renderer.render(scene,camera)});$('#loading').style.display='none'}
function resize(){const r=container.getBoundingClientRect();if(!r.width||!r.height)return;camera.aspect=r.width/r.height;camera.updateProjectionMatrix();renderer.setSize(r.width,r.height,false)}
function setView(mode){const views={perspective:[[210,150,-260],[0,52,-15],'透视视图','下游三分之四视角'],front:[[0,65,-330],[0,55,0],'下游立面','自下游看上游：北／左岸在左'],cross:[[-330,70,0],[0,55,-10],'典型横剖面','沿坝轴向西北观察：上游在左、下游在右'],top:[[0,360,0],[0,35,-15],'坝顶俯视','西北／左岸在上游观察方向左侧']},v=views[mode];camera.position.set(...v[0]);controls.target.set(...v[1]);controls.update();$('#viewTitle').textContent=v[2];$('#direction').textContent=v[3];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode))}
function renderList(){const h=$('#candidateList');h.innerHTML='';candidates.forEach((c,i)=>{const d=document.createElement('div');d.className='candidate'+(i===active?' active':'');d.innerHTML=`<b>${c.name}</b><span>x ${c.x.toFixed(1)} · y ${c.y.toFixed(1)} · ▽${c.z.toFixed(1)}</span>`;d.onclick=()=>{active=i;sync();renderList();updateDetector()};h.append(d)})}
function sync(){const c=candidates[active];for(const k of ['name','x','y','z','az','el','fov'])$('#'+k).value=c[k];$('#azOut').textContent=c.az+'°';$('#elOut').textContent=c.el+'°';$('#fovOut').textContent=c.fov+'°'}
function updateWater(kind){const id=kind==='upwater'?'upLevel':'downLevel',out=kind==='upwater'?'upOut':'downOut',up=kind==='upwater';$('#'+out).textContent='▽'+$('#'+id).value+' m';groups[kind].clear();groups[kind].add(waterMesh(up?'上游库水':'下游尾水',+$('#'+id).value,up));updateDetector()}
function bind(){for(const k of ['name','x','y','z','az','el','fov'])$('#'+k).addEventListener('input',e=>{candidates[active][k]=k==='name'?e.target.value:+e.target.value;sync();renderList();updateDetector()});$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-layer]').forEach(e=>e.onchange=()=>groups[e.dataset.layer].visible=e.checked);$('#upLevel').oninput=()=>updateWater('upwater');$('#downLevel').oninput=()=>updateWater('downwater');$('#gridSize').oninput=()=>{$('#gridOut').textContent=(+$('#gridSize').value).toFixed(1)+' m';updateDetector()};$('#add').onclick=()=>{candidates.push({...candidates[active],name:'新候选点 '+(candidates.length+1)});active=candidates.length-1;sync();renderList();updateDetector()};$('#duplicate').onclick=$('#add').onclick;$('#remove').onclick=()=>{if(candidates.length<2)return;candidates.splice(active,1);active=Math.max(0,active-1);sync();renderList();updateDetector()};$('#save').onclick=()=>{localStorage.setItem('muon-three-candidates-v2',JSON.stringify(candidates));$('#saved').textContent='已保存到本机浏览器。'};$('#export').onclick=()=>{const c=candidates[active],cell=+$('#gridSize').value,ray=traceRay(new THREE.Vector3(c.x,c.y,c.z),directionDoc(c),cell),data={model:'周宁下库大坝 LOD2 体素射线模型',spec_version:spec.spec_version,coordinates:spec.conventions.model_frame,grid_cell_m:cell,water:{upstream:+$('#upLevel').value,downstream:+$('#downLevel').value},active_ray:{detector:c,material_path_m:ray.totals,column_density_mwe:ray.mwe},candidates};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='周宁缪子部署网格射线方案.json';a.click();URL.revokeObjectURL(a.href)};window.addEventListener('resize',resize)}

async function main(){spec=await fetch('./data/dam_spec.json').then(r=>{if(!r.ok)throw Error('规格文件读取失败');return r.json()});$('#specVersion').textContent=spec.spec_version;$('#upLevel').value=spec.parameters.water_up_level.value;$('#downLevel').value=spec.parameters.water_tail_level.value;$('#upOut').textContent='▽'+$('#upLevel').value+' m';$('#downOut').textContent='▽'+$('#downLevel').value+' m';candidates=defaultCandidates();try{const saved=JSON.parse(localStorage.getItem('muon-three-candidates-v2'));if(Array.isArray(saved)&&saved.length)candidates=saved}catch{}renderList();sync();buildScene();bind()}
main().catch(err=>{console.error(err);$('#loading').textContent='结构规格或三维引擎加载失败，请刷新后重试。';$('#loading').classList.add('error')});
